// Оценка 0-6 в шкале 0-10 (99 = «Не знаю» не считается)
function isLowScore(score) {
    return score !== undefined && score >= 0 && score <= 6;
}

// Q11-Q12: Ювидерм (кат.1, при оценке 0-6) + до 2 случайных
// брендов с оценкой 0-6. Ранее выбранные бренды сохраняются (при возврате назад выбор не меняется).
function pickLowScoreBrands(Q, q10, cat) {
    let low = [];
    let juvederm = false;
    for (let row of q10.rows.getVisible()) {
        let score = row.getCheckedCode(true);
        if (cat === 1 && row.code === 2) {
            juvederm = isLowScore(score);
        } else if (isLowScore(score)) {
            low.push(row.code);
        }
    }
    let chosen = Q.getCheckedCodes().filter(function (code) { return low.indexOf(code) > -1; });
    chosen = chosen.slice(0, 2);
    for (let code of randomizeArray(low)) {
        if (chosen.length >= 2) break;
        if (chosen.indexOf(code) === -1) chosen.push(code);
    }
    if (juvederm) chosen.push(2);
    Q.reset();
    for (let code of chosen) Q[code].checked = true;
    return Q.isAnswered ? answered : skip;
}

// Категории с S3 > 0 в порядке блоков раздела 2 в анкете
function categoryOrder() {
    let numbers = questions.getNumbers();
    let first = {1: 10810, 2: 10820, 3: 10830};
    return [1, 2, 3].filter(catActive).sort(function (a, b) {
        return numbers.indexOf(first[a]) - numbers.indexOf(first[b]);
    });
}

